//! A branch is a separate project. Lineage is portable provenance, never a write authority.
use crate::{Storage,Scene,Revision,ProjectBundle,validate};
use crate::workspace::{append,err,hash,id,revision,remap_payload,title,validate_data,validate_scene_links,ProjectDataEntry};
use crate::time_machine::exact_heads;
use serde::{Serialize,Deserialize};
use serde_json::{Value,json};
use sqlx::{Sqlite,Transaction};
use std::collections::{HashMap,HashSet};
#[derive(Debug,Clone,Serialize,Deserialize)]
#[serde(rename_all="camelCase",deny_unknown_fields)]
pub struct BranchMapping {pub source_id:String,pub branch_id:String}
#[derive(Debug,Clone,Serialize,Deserialize)]
#[serde(rename_all="camelCase",deny_unknown_fields)]
pub struct BranchSceneMapping {pub source_scene_id:String,pub branch_scene_id:String,pub source_baseline_revision_id:String,pub branch_baseline_revision_id:String}
#[derive(Debug,Clone,Serialize,Deserialize)]
#[serde(rename_all="camelCase",deny_unknown_fields)]
pub struct BranchOrigin {pub id:String,pub source_project_id:String,pub branch_project_id:String,pub source_archive_checksum:String,pub scene_mappings:Vec<BranchSceneMapping>,pub id_mappings:Vec<BranchMapping>,pub source_planning_revision_id:Option<String>,pub branch_planning_baseline_revision_id:Option<String>}
#[derive(Debug,Clone,Serialize,Deserialize)]
#[serde(rename_all="camelCase",deny_unknown_fields)]
pub struct BranchLineage {pub schema_version:u32,pub active_origin_id:String,pub origins:Vec<BranchOrigin>}
#[derive(Debug,Clone,Serialize,Deserialize)]
#[serde(rename_all="camelCase")]
pub struct BranchInfo {pub project_id:String,pub title:String,pub source_project_id:String,pub lineage_revision_id:String,pub origin_id:String,pub scene_count:usize}
#[derive(Debug,Clone,Serialize,Deserialize)]
#[serde(rename_all="camelCase")]
pub struct BranchPiece {pub entity_type:String,pub source_entity_id:Option<String>,pub branch_entity_id:String,pub title:String,pub source_head_ids:Vec<String>,pub branch_head_ids:Vec<String>,pub source_baseline_revision_id:Option<String>,pub branch_baseline_revision_id:Option<String>,pub source_changed:bool,pub branch_changed:bool,pub differs:bool,pub can_bring_back:bool,pub warning:Option<String>}
#[derive(Debug,Clone,Serialize,Deserialize)]
#[serde(rename_all="camelCase")]
pub struct BranchComparison {pub branch:BranchInfo,pub pieces:Vec<BranchPiece>,pub offset:u32,pub total:usize,pub has_more:bool,pub warnings:Vec<String>}
fn lineage(value:&Value)->Result<BranchLineage,String>{let data:BranchLineage=serde_json::from_value(value.clone()).map_err(|_|"Invalid branch lineage schema.")?;if data.schema_version!=1||data.origins.is_empty()||data.origins.len()>100||!data.origins.iter().any(|o|o.id==data.active_origin_id){return Err("Invalid branch origin selection.".into())}let mut origins=HashSet::new();for o in &data.origins{if !origins.insert(&o.id)||!crate::workspace::valid_id(&o.id)||!crate::workspace::valid_id(&o.source_project_id)||!crate::workspace::valid_id(&o.branch_project_id)||o.source_project_id==o.branch_project_id||o.source_archive_checksum.len()!=64||!o.source_archive_checksum.bytes().all(|b|b.is_ascii_hexdigit())||o.scene_mappings.len()>10000||o.id_mappings.len()>100000{return Err("Invalid or oversized branch origin.".into())}let(mut sources,mut targets)=(HashSet::new(),HashSet::new());for m in &o.id_mappings{if !crate::workspace::valid_id(&m.source_id)||!crate::workspace::valid_id(&m.branch_id)||!sources.insert(&m.source_id)||!targets.insert(&m.branch_id){return Err("Invalid branch identity map.".into())}}let maps=o.id_mappings.iter().map(|m|(&m.source_id,&m.branch_id)).collect::<HashMap<_,_>>();let mut scenes=HashSet::new();for m in &o.scene_mappings{if !scenes.insert(&m.source_scene_id)||maps.get(&m.source_scene_id)!=Some(&&m.branch_scene_id)||maps.get(&m.source_baseline_revision_id)!=Some(&&m.branch_baseline_revision_id){return Err("Invalid branch scene baseline map.".into())}}if maps.get(&o.source_project_id)!=Some(&&o.branch_project_id)||o.source_planning_revision_id.as_ref().map(|s|maps.get(s).copied())!=o.branch_planning_baseline_revision_id.as_ref().map(Some){return Err("Invalid branch planning baseline map.".into())}}
 Ok(data)}
pub(crate) fn validate_lineage(value:&Value)->Result<(),String>{lineage(value).map(|_|())}
pub(crate) fn lineage_transition(old:&Value,new:&Value)->Result<(),String>{let old=lineage(old)?;let new=lineage(new)?;let a=serde_json::to_value(&old.origins).unwrap();let b=serde_json::to_value(&new.origins).unwrap();if a.as_array().unwrap().iter().any(|origin|!b.as_array().unwrap().contains(origin))||new.origins.len()<old.origins.len()||(new.active_origin_id!=old.active_origin_id&&old.origins.iter().any(|o|o.id==new.active_origin_id)){return Err("Branch origins and baseline mappings are immutable.".into())}Ok(())}
pub(crate) async fn record_origin(tx:&mut Transaction<'_,Sqlite>,pid:&str,source:&str,label:&str,bundle:&ProjectBundle,data:&[ProjectDataEntry],ids:&HashMap<String,String>,encoded:&str)->Result<(),String>{
 title(label)?;let previous:Option<(String,String)>=sqlx::query_as("SELECT d.head,r.payload FROM project_data d JOIN revision_envelope r ON r.id=d.head WHERE d.project_id=? AND d.kind='branchLineage'").bind(pid).fetch_optional(&mut **tx).await.map_err(err)?;
 let mut origins=if let Some((_,payload))=&previous{lineage(&serde_json::from_str(payload).map_err(|_|"Invalid copied branch origin.")?)?.origins}else{vec![]};
 let planning=data.iter().find(|d|d.kind=="planning").map(|d|d.revision_id.clone());let oid=id();let mut mappings=ids.iter().map(|(s,b)|BranchMapping{source_id:s.clone(),branch_id:b.clone()}).collect::<Vec<_>>();mappings.sort_by(|a,b|a.source_id.cmp(&b.source_id));
 origins.push(BranchOrigin{id:oid.clone(),source_project_id:source.into(),branch_project_id:pid.into(),source_archive_checksum:hash(encoded.as_bytes()),scene_mappings:bundle.scenes.iter().map(|s|BranchSceneMapping{source_scene_id:s.id.clone(),branch_scene_id:ids[&s.id].clone(),source_baseline_revision_id:s.revision_id.clone(),branch_baseline_revision_id:ids[&s.revision_id].clone()}).collect(),id_mappings:mappings,source_planning_revision_id:planning.clone(),branch_planning_baseline_revision_id:planning.map(|r|ids[&r].clone())});
 let payload=serde_json::to_value(BranchLineage{schema_version:1,active_origin_id:oid,origins}).unwrap();validate_data("branchLineage",&payload)?;
 let fresh=id();append(tx,pid,&format!("{pid}:branchLineage"),"projectData",previous.map(|p|p.0).into_iter().collect(),payload,"branchLineage",&fresh).await?;
 sqlx::query("INSERT INTO project_data(project_id,kind,head) VALUES(?,'branchLineage',?) ON CONFLICT(project_id,kind) DO UPDATE SET head=excluded.head").bind(pid).bind(&fresh).execute(&mut **tx).await.map_err(err)?;
 let parents:Vec<String>=sqlx::query_scalar("SELECT r.id FROM revision_envelope r WHERE project_id=? AND entity_id=? AND entity_type='project' AND NOT EXISTS(SELECT 1 FROM revision_envelope c,json_each(c.parents) p WHERE c.entity_id=r.entity_id AND p.value=r.id)").bind(pid).bind(pid).fetch_all(&mut **tx).await.map_err(err)?;
 if parents.len()>1{return Err("Resolve competing project metadata before creating a branch.".into())}
 let order:Vec<String>=sqlx::query_scalar("SELECT id FROM chapter WHERE project_id=? ORDER BY position,id").bind(pid).fetch_all(&mut **tx).await.map_err(err)?;
 append(tx,pid,pid,"project",parents,json!({"title":label,"order":order}),"branchCreate",&id()).await?;
 sqlx::query("UPDATE project SET title=? WHERE id=?").bind(label).bind(pid).execute(&mut **tx).await.map_err(err)?;Ok(())
}
async fn checked_revision(tx:&mut Transaction<'_,Sqlite>,pid:&str,entity:&str,kind:&str,rid:&str)->Result<Revision,String>{let types=if kind=="scene"{"('scene','tombstone')"}else{"('projectData')"};let row=sqlx::query(&format!("SELECT r.*,m.sequence FROM revision_envelope r JOIN change_marker m ON m.revision_id=r.id WHERE r.id=? AND r.project_id=? AND r.entity_id=? AND r.entity_type IN{types}")).bind(rid).bind(pid).bind(entity).fetch_optional(&mut **tx).await.map_err(err)?.ok_or("Branch revision does not belong to this project and piece.")?;let r=revision(row)?;if r.schema_version!=1||hash(serde_json::to_string(&r.payload).unwrap().as_bytes())!=r.checksum{return Err("Branch revision checksum failed. Nothing was copied.".into())}Ok(r)}
async fn active(tx:&mut Transaction<'_,Sqlite>,source:&str,pid:&str)->Result<(BranchInfo,BranchOrigin),String>{
 if source==pid{return Err("Choose a separate branch project.".into())}
 let row:Option<(String,String)>=sqlx::query_as("SELECT p.title,d.head FROM project p JOIN project_data d ON d.project_id=p.id JOIN revision_envelope r ON r.id=d.head WHERE p.id=? AND d.kind='branchLineage'").bind(pid).fetch_optional(&mut **tx).await.map_err(err)?;
 let(title,rid)=row.ok_or("This project has no branch lineage.")?;if exact_heads(tx,pid,&format!("{pid}:branchLineage"),"projectData").await?!=vec![rid.clone()]{return Err("Resolve competing branch lineage before comparing.".into())}
 let saved=checked_revision(tx,pid,&format!("{pid}:branchLineage"),"projectData",&rid).await?;let data=lineage(&saved.payload)?;let origin=data.origins.into_iter().find(|o|o.id==data.active_origin_id).unwrap();if origin.source_project_id!=source||origin.branch_project_id!=pid{return Err("Branch lineage does not belong to this source and branch project.".into())}
 let exists:i64=sqlx::query_scalar("SELECT count(*) FROM project WHERE id=?").bind(source).fetch_one(&mut **tx).await.map_err(err)?;if exists!=1{return Err("The source project is unavailable. Import it before comparing.".into())}
 Ok((BranchInfo{project_id:pid.into(),title,source_project_id:source.into(),lineage_revision_id:rid,origin_id:origin.id.clone(),scene_count:origin.scene_mappings.len()},origin))
}
fn reverse(origin:&BranchOrigin)->HashMap<String,String>{origin.id_mappings.iter().map(|m|(m.branch_id.clone(),m.source_id.clone())).collect()}
async fn payloads(tx:&mut Transaction<'_,Sqlite>,pid:&str,entity:&str,kind:&str,heads:&[String],map:Option<&HashMap<String,String>>)->Result<Vec<Value>,String>{if heads.len()>100{return Err("More than 100 competing heads; resolve conflicts before comparing.".into())}let mut values=vec![];for rid in heads{let mut r=checked_revision(tx,pid,entity,kind,rid).await?;if let Some(map)=map{remap_payload(&mut r.payload,map);}values.push(r.payload);}Ok(values)}
impl Storage{
 pub async fn create_project_branch(&self,source:&str,label:&str)->Result<BranchInfo,String>{title(label)?;let archive=self.export_archive(source).await?;let bundle=self.import_archive_internal(&archive,Some(label)).await?;let mut tx=self.pool.begin().await.map_err(err)?;let info=active(&mut tx,source,&bundle.project.id).await?.0;tx.commit().await.map_err(err)?;Ok(info)}
 pub async fn list_project_branches(&self,source:&str)->Result<Vec<BranchInfo>,String>{let mut tx=self.pool.begin().await.map_err(err)?;let pids:Vec<String>=sqlx::query_scalar("SELECT d.project_id FROM project_data d JOIN revision_envelope r ON r.id=d.head WHERE d.kind='branchLineage' AND EXISTS(SELECT 1 FROM json_each(r.payload,'$.origins') o WHERE json_extract(o.value,'$.id')=json_extract(r.payload,'$.activeOriginId') AND json_extract(o.value,'$.sourceProjectId')=?) ORDER BY d.project_id LIMIT 101").bind(source).fetch_all(&mut *tx).await.map_err(err)?;if pids.len()>100{return Err("More than 100 branches: open the desired branch from Projects.".into())}let mut results=vec![];for pid in pids{results.push(active(&mut tx,source,&pid).await?.0)}tx.commit().await.map_err(err)?;Ok(results)}
 pub async fn compare_project_branch(&self,source:&str,pid:&str,offset:u32,limit:u32)->Result<BranchComparison,String>{
 if !(1..=100).contains(&limit)||offset>10000{return Err("Compare 1–100 pieces at a time.".into())}let mut tx=self.pool.begin().await.map_err(err)?;let(info,origin)=active(&mut tx,source,pid).await?;let reverse=reverse(&origin);
 let mut specs=origin.scene_mappings.iter().map(|m|("scene",Some(m.source_scene_id.clone()),m.branch_scene_id.clone(),Some(m.source_baseline_revision_id.clone()),Some(m.branch_baseline_revision_id.clone()))).collect::<Vec<_>>();
 let branch_ids:Vec<String>=sqlx::query_scalar("SELECT s.id FROM manuscript_scene s JOIN chapter c ON c.id=s.chapter_id WHERE c.project_id=? ORDER BY c.position,s.position,s.id LIMIT 10001").bind(pid).fetch_all(&mut *tx).await.map_err(err)?;if branch_ids.len()>10000{return Err("Branch comparison exceeds 10,000 scenes.".into())}let mapped:HashSet<&str>=origin.scene_mappings.iter().map(|m|m.branch_scene_id.as_str()).collect();for eid in branch_ids{if !mapped.contains(eid.as_str()){specs.push(("scene",None,eid,None,None));}}
 let branch_bible=exact_heads(&mut tx,pid,&format!("{pid}:planning"),"projectData").await?;if !branch_bible.is_empty()||origin.source_planning_revision_id.is_some(){specs.push(("projectData",Some(format!("{source}:planning")),format!("{pid}:planning"),origin.source_planning_revision_id.clone(),origin.branch_planning_baseline_revision_id.clone()));}
 let total=specs.len();let mut pieces=vec![];for(kind,target,entity,baseline,branch_baseline)in specs.into_iter().skip(offset as usize).take(limit as usize){
 let bh=exact_heads(&mut tx,pid,&entity,kind).await?;let sh=if let Some(eid)=&target{exact_heads(&mut tx,source,eid,kind).await?}else{vec![]};let bp=payloads(&mut tx,pid,&entity,kind,&bh,Some(&reverse)).await?;let sp=if let Some(eid)=&target{payloads(&mut tx,source,eid,kind,&sh,None).await?}else{vec![]};
 let base=if let(Some(eid),Some(rid))=(&target,&baseline){payloads(&mut tx,source,eid,kind,&[rid.clone()],None).await?}else{vec![]};let copied=if let Some(rid)=&branch_baseline{payloads(&mut tx,pid,&entity,kind,&[rid.clone()],Some(&reverse)).await?}else{vec![]};if base!=copied{return Err("Branch baseline no longer matches its verified source. Nothing was copied.".into())}
 let deletion=bp.iter().any(|p|p.get("deleted")==Some(&Value::Bool(true)));let warning=if target.is_none(){Some("New branch scene: copy it manually into the source if wanted.".into())}else if bh.len()!=1||sh.len()>1{Some("Resolve competing versions before bringing this piece back.".into())}else if deletion{Some("Branch deletion is preview-only; source deletion requires an explicit separate action.".into())}else{None};
 let name=if kind=="projectData"{"Whole story bible".into()}else{bp.first().or(sp.first()).and_then(|p|p["title"].as_str()).unwrap_or("Deleted scene").into()};let can=target.is_some()&&bh.len()==1&&(sh.len()==1||kind=="projectData")&&!deletion;
 pieces.push(BranchPiece{entity_type:kind.into(),source_entity_id:target,branch_entity_id:entity,title:name,source_head_ids:sh,branch_head_ids:bh,source_baseline_revision_id:baseline,branch_baseline_revision_id:branch_baseline,source_changed:sp!=base,branch_changed:bp!=copied,differs:sp!=bp,can_bring_back:can,warning});}
 tx.commit().await.map_err(err)?;Ok(BranchComparison{branch:info,pieces,offset,total,has_more:offset as usize+(limit as usize)<total,warnings:vec!["Bringing back a piece creates a new source revision. Scene order, chapters, project settings and branch deletions are not merged.".into()]})
 }
 pub async fn bring_back_branch_piece(&self,source:&str,pid:&str,lineage_revision_id:&str,entity:&str,kind:&str,rid:&str,expected_source_heads:Vec<String>,expected_branch_heads:Vec<String>)->Result<Revision,String>{
 let mut tx=self.pool.begin().await.map_err(err)?;let(info,origin)=active(&mut tx,source,pid).await?;if info.lineage_revision_id!=lineage_revision_id{return Err("Conflict: branch lineage changed. Compare again.".into())}
 let (target,baseline,copied)=if kind=="scene"{let m=origin.scene_mappings.iter().find(|m|m.branch_scene_id==entity).ok_or("This scene has no verified source mapping.")?;(m.source_scene_id.clone(),Some(m.source_baseline_revision_id.clone()),Some(m.branch_baseline_revision_id.clone()))}else if kind=="projectData"&&entity==format!("{pid}:planning"){(format!("{source}:planning"),origin.source_planning_revision_id.clone(),origin.branch_planning_baseline_revision_id.clone())}else{return Err("Bring back one mapped scene or the whole story bible explicitly.".into())};
 let bh=exact_heads(&mut tx,pid,entity,kind).await?;let sh=exact_heads(&mut tx,source,&target,kind).await?;if bh.len()!=1||bh!=expected_branch_heads||bh!=vec![rid.to_string()]||sh.len()>1||sh!=expected_source_heads||(kind=="scene"&&sh.len()!=1){return Err("Conflict: source or branch changed since comparison. Nothing was replaced.".into())}
 let reverse=reverse(&origin);payloads(&mut tx,source,&target,kind,&sh,None).await?;let original=if let Some(id)=baseline{payloads(&mut tx,source,&target,kind,&[id],None).await?}else{vec![]};let fork=if let Some(id)=copied{payloads(&mut tx,pid,entity,kind,&[id],Some(&reverse)).await?}else{vec![]};if original!=fork{return Err("Branch baseline verification failed. Nothing was copied.".into())}
 let mut selected=checked_revision(&mut tx,pid,entity,kind,rid).await?;remap_payload(&mut selected.payload,&reverse);let fresh=id();
 if kind=="scene"{if selected.entity_type!="scene"{return Err("Branch deletions cannot be brought back automatically.".into())}let scene:Scene=serde_json::from_value(selected.payload.clone()).map_err(|_|"Invalid branch scene.")?;validate(&scene)?;let owner:Option<String>=sqlx::query_scalar("SELECT c.project_id FROM manuscript_scene s JOIN chapter c ON c.id=s.chapter_id WHERE s.id=?").bind(&target).fetch_optional(&mut *tx).await.map_err(err)?;if owner.as_deref()!=Some(source){return Err("Source scene ownership changed.".into())}
 append(&mut tx,source,&target,"scene",sh,selected.payload,"branchBringBack",&fresh).await?;sqlx::query("UPDATE manuscript_scene SET head=?,deleted=0 WHERE id=?").bind(&fresh).bind(&target).execute(&mut *tx).await.map_err(err)?;crate::sync::recompute_scene_heads(&mut tx,&target).await?;
 }else{let projected:Option<String>=sqlx::query_scalar("SELECT head FROM project_data WHERE project_id=? AND kind='planning'").bind(source).fetch_optional(&mut *tx).await.map_err(err)?;if projected.as_ref()!=sh.first(){return Err("Conflict: source story bible projection changed. Compare again.".into())}if selected.operation!="planning"{return Err("This branch piece is not a story bible.".into())}validate_data("planning",&selected.payload)?;let scene_ids:Vec<String>=sqlx::query_scalar("SELECT s.id FROM manuscript_scene s JOIN chapter c ON c.id=s.chapter_id WHERE c.project_id=?").bind(source).fetch_all(&mut *tx).await.map_err(err)?;validate_scene_links(&selected.payload,&scene_ids.into_iter().collect())?;
 append(&mut tx,source,&target,"projectData",sh,selected.payload,"planning",&fresh).await?;sqlx::query("INSERT INTO project_data(project_id,kind,head) VALUES(?,'planning',?) ON CONFLICT(project_id,kind) DO UPDATE SET head=excluded.head").bind(source).bind(&fresh).execute(&mut *tx).await.map_err(err)?;}
 let result=revision(sqlx::query("SELECT r.*,m.sequence FROM revision_envelope r JOIN change_marker m ON m.revision_id=r.id WHERE r.id=?").bind(&fresh).fetch_one(&mut *tx).await.map_err(err)?)?;tx.commit().await.map_err(err)?;Ok(result)
 }
}
